// Base64-encoded woff2 Latin subsets for embedding in OG/diploma SVGs.
// These are generated offline from the source TTFs and committed as constants
// so no build-time font tooling is needed at deploy time.
//
// Subset scope: U+0020-007E (Basic Latin) + U+00A0-017F (Latin-1 + Extended-A).
// Covers: A-Z a-z 0-9, punctuation, ¡ ¿ « » accented Spanish/European chars.
//
// Space Mono is NOT embedded — it falls back to ui-monospace / Courier New in
// the SVG renderer; the verify URL at 17px is legible in any monospace.
//
// To regenerate (requires fonttools: pip install fonttools):
//   pyftsubset <Lora-variable.ttf> --unicodes="U+0020-007E,U+00A0-017F" \
//     --layout-features="*" --flavor=woff2 --output-file=Lora-subset.woff2
//   pyftsubset <Lora-Italic-variable.ttf> --unicodes="U+0020-007E,U+00A0-017F" \
//     --layout-features="*" --flavor=woff2 --output-file=Lora-Italic-subset.woff2
//   python3 -c "import base64; print(base64.b64encode(open('Lora-subset.woff2','rb').read()).decode())"

export const LORA_WOFF2 =
  'data:font/woff2;base64,' as const;

export const LORA_ITALIC_WOFF2 =
  'data:font/woff2;base64,' as const;
